 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find horizontal and vertical grid lines: lines whose predominant value is
    # not the open-cell background and covers most of the line.
    rows = []
    row_colors = {}
    for r, row in enumerate(grid):
        c = Counter(row)
        color, n = c.most_common(1)[0]
        if color != background and n >= 0.65 * w:
            rows.append(r)
            row_colors[r] = color
    cols = []
    col_colors = {}
    for x in range(w):
        c = Counter(grid[r][x] for r in range(h))
        color, n = c.most_common(1)[0]
        if color != background and n >= 0.65 * h:
            cols.append(x)
            col_colors[x] = color

    if len(rows) < 2 or len(cols) < 2:
        # Degenerate single-cell lattice (e.g. two marked horizontal/vertical
        # boundaries enclosing one uniform marker).
        nonbg = [v for row in grid for v in row if v != background]
        return [[Counter(nonbg).most_common(1)[0][0]]] if nonbg else [[background]]

    # Keep vertical grid lines carrying marker colors at their crossings.
    marked_cols = []
    for x in cols:
        sep = col_colors[x]
        if any(grid[r][x] != sep and grid[r][x] != background for r in rows):
            marked_cols.append(x)

    # Consecutive marked columns form pairs. Each pair is a compact output
    # column; a blank/background column separates successive pairs.
    pairs = [marked_cols[i:i + 2] for i in range(0, len(marked_cols), 2) if len(marked_cols[i:i + 2]) == 2]
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        outrow = []
        for pi, (c0, c1) in enumerate(pairs):
            v = grid[r0][c0]
            vals = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            sep0, sep1 = col_colors[c0], col_colors[c1]
            if vals.count(v) == 4 and v != sep0 and v != sep1 and v != background:
                outrow.append(v)
            else:
                outrow.append(background)
            if pi < len(pairs) - 1:
                outrow.append(background)
        out.append(outrow)
    return out


if __name__ == "__main__":
    pass
